// Parity with the Electron 0.1.6 formula engine: every case in
// test/fixtures/formula/formula-corpus.json (generated by the vitest oracle
// beside it) must give the same value, error, syntax flag, validation
// message and variable list.
import 'dart:convert';
import 'dart:io';

import 'package:anvil_core/anvil_core.dart';
import 'package:path/path.dart' as p;
import 'package:test/test.dart';

import '../db/support/fixture_copy.dart' show fixturesDir;

/// The corpus encoding: JSON numbers, or 'NaN' / 'Infinity' / '-Infinity' /
/// '-0' strings.
double _decode(Object? v) => switch (v) {
  num() => v.toDouble(),
  '-0' => -0.0,
  String() => double.parse(v),
  _ => throw ArgumentError.value(v, 'corpus number'),
};

String _formula(Map<String, Object?> c) {
  final repeat = c['repeat'] as Map<String, Object?>?;
  if (repeat == null) return c['formula'] as String;
  final depth = repeat['depth'] as int;
  return (repeat['open'] as String) * depth +
      (repeat['core'] as String) +
      (repeat['close'] as String) * depth;
}

Map<String, double> _bindings(Map<String, Object?> c) => {
  for (final MapEntry(:key, :value)
      in (c['bindings'] as Map<String, Object?>).entries)
    key: _decode(value),
};

String _label(Map<String, Object?> c) {
  if (c['repeat'] case final Map<String, Object?> r) {
    return 'repeat ${jsonEncode(r)}';
  }
  final f = jsonEncode(c['formula']);
  return f.length > 50 ? '${f.substring(0, 50)}…' : f;
}

/// Exact double equality that also tells -0 from 0 and treats NaN as equal.
Matcher _sameDouble(double expected) => predicate<double?>(
  (actual) =>
      actual != null &&
      (expected.isNaN
          ? actual.isNaN
          : actual == expected && actual.isNegative == expected.isNegative),
  'exactly $expected',
);

void _expectResult(FormulaEvalResult actual, Map<String, Object?> c) {
  final expectedValue = c['value'];
  if (expectedValue == null) {
    expect(actual.value, isNull, reason: 'value');
  } else {
    expect(actual.value, _sameDouble(_decode(expectedValue)), reason: 'value');
  }
  expect(actual.error, c['error'], reason: 'error');
  expect(actual.isSyntaxError, c['isSyntaxError'], reason: 'isSyntaxError');
}

void main() {
  final corpus = jsonDecode(
    File(p.join(fixturesDir, 'formula', 'formula-corpus.json'))
        .readAsStringSync(),
  ) as Map<String, Object?>;
  final cases = (corpus['cases'] as List).cast<Map<String, Object?>>();

  test('the corpus holds at least 120 cases (${cases.length})', () {
    expect(cases.length, greaterThanOrEqualTo(120));
  });

  group('evaluateFormula / validateFormula / extractVariableNames', () {
    for (final (i, c) in cases.indexed) {
      test('#$i ${_label(c)}', () {
        final formula = _formula(c);
        _expectResult(evaluateFormula(formula, _bindings(c)), c);
        expect(validateFormula(formula), c['validate'], reason: 'validate');
        expect(
          extractVariableNames(formula),
          c['variables'],
          reason: 'variables',
        );
      });
    }
  });

  test('a FormulaEngine gives the corpus results, cold and cached', () {
    final engine = FormulaEngine();
    for (final pass in ['cold', 'cached']) {
      for (final c in cases) {
        final formula = _formula(c);
        final label = '$pass ${_label(c)}';
        final result = engine.evaluate(formula, _bindings(c));
        expect(result.error, c['error'], reason: label);
        expect(result.isSyntaxError, c['isSyntaxError'], reason: label);
        if (c['value'] case final Object v) {
          expect(result.value, _sameDouble(_decode(v)), reason: label);
        }
        expect(engine.validate(formula), c['validate'], reason: label);
        expect(engine.extractVariableNames(formula), c['variables']);
      }
    }
  });
}
